fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    // If the input is empty, return an empty Vec
    if n == 0 {
        return Vec::new();
    }

    // Preallocate the result with the exact capacity we need: 2*n - 1
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        res.push(num);
        // After each element except the last, push the delimiter
        if i + 1 < n {
            res.push(delim);
        }
    }

    res
}

